export const ALIAS_DE_ICONO: Readonly<Record<string, string>> = {
  home: 'house',
  cart: 'shoppingCart',
  bolt: 'zap',
};

export function iconoDeCategoria(valor: string | null | undefined): string | null {
  if (!valor) return null;
  const clave = ALIAS_DE_ICONO[valor] ?? valor;
  return clave in ICONOS_DE_CATEGORIA ? clave : null;
}

export const NOMBRES_DE_ICONO = Object.keys(ICONOS_DE_CATEGORIA);
